import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CyZTVJbV.js";const v=JSON.parse('{"title":"@kiwa-lab/lean v0.2 verify integration SSOT","description":"","frontmatter":{"title":"@kiwa-lab/lean v0.2 verify integration SSOT"},"headers":[],"relativePath":"concepts/lean-verify-integration.md","filePath":"concepts/lean-verify-integration.md"}'),n={name:"concepts/lean-verify-integration.md"};function c(l,e,s,d,r,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="kiwa-lab-lean-v0-2-verify-integration-ssot" tabindex="-1">@kiwa-lab/lean v0.2 verify integration SSOT <a class="header-anchor" href="#kiwa-lab-lean-v0-2-verify-integration-ssot" aria-label="Permalink to &quot;@kiwa-lab/lean v0.2 verify integration SSOT&quot;">​</a></h1><h2 id="what-this-covers" tabindex="-1">What this covers <a class="header-anchor" href="#what-this-covers" aria-label="Permalink to &quot;What this covers&quot;">​</a></h2><p>v2.14 で追加した <code>@kiwa-lab/lean</code> v0.1 spec generator を v0.2 で <code>verifyLeanSpec</code> 統合、 生成 Lean file を <strong>実際に Lean toolchain で検証</strong> する Level 2 layer 追加。 kiwa 全体 branding「testing + 形式検証」 の pipeline を完成、 systematic pattern 57 度目。</p><h2 id="level-1-vs-level-2" tabindex="-1">Level 1 vs Level 2 <a class="header-anchor" href="#level-1-vs-level-2" aria-label="Permalink to &quot;Level 1 vs Level 2&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>v0.1</th><th>v0.2</th></tr></thead><tbody><tr><td>generateLeanSpec</td><td>✅ Lean source 生成</td><td>✅ 変更 0 (shape preserving)</td></tr><tr><td>generateLakeProject</td><td>✅ Lake scaffold 生成</td><td>✅ v0.3 で修正 (下記)</td></tr><tr><td>verifyLeanSpec</td><td>❌</td><td>✅ 新規 = 実 toolchain 呼出 (<code>lean FILE</code>)</td></tr></tbody></table><h2 id="verifyleanspec-api-ssot" tabindex="-1">verifyLeanSpec API SSOT <a class="header-anchor" href="#verifyleanspec-api-ssot" aria-label="Permalink to &quot;verifyLeanSpec API SSOT&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">verifyLeanSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(specs: readonly LeanSpecOutput[], opts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VerifyOptions): VerifyResult;</span></span></code></pre></div><h3 id="_3-経路-verifystatus" tabindex="-1">3 経路 (VerifyStatus) <a class="header-anchor" href="#_3-経路-verifystatus" aria-label="Permalink to &quot;3 経路 (VerifyStatus)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>status</th><th>発火条件</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Lean install 済 + 全 spec の elaboration 成功</td></tr><tr><td><code>verification-failed</code></td><td>Lean install 済 + いずれかの spec の elaboration 失敗 (<code>diagnostics</code> に Lean の出力を添付)</td></tr><tr><td><code>lean-not-installed</code></td><td>Lean toolchain 未 install (throw なし return)</td></tr><tr><td><code>skipped-by-env</code></td><td><code>KIWA_LEAN_SKIP_VERIFY=1</code> env or <code>opts.skip=true</code></td></tr></tbody></table><h3 id="lake-project-は何も建てていなかった-v0-3-で修正" tabindex="-1">Lake project は何も建てていなかった (v0.3 で修正) <a class="header-anchor" href="#lake-project-は何も建てていなかった-v0-3-で修正" aria-label="Permalink to &quot;Lake project は何も建てていなかった (v0.3 で修正)&quot;">​</a></h3><p>生成される <code>lakefile.lean</code> の <code>lean_lib</code> に <code>@[default_target]</code> が無く、 <code>lake build</code> は対象を 1 つも持たなかった。 spec に型エラーがあっても <code>Build completed successfully</code> と表示して 0 で終了する。 さらに根 module が spec を <code>import</code> せず、 <code>globs</code> も無いため、 仮に対象があっても spec file は 1 度もコンパイルされなかった。</p><p>v0.3 は <code>@[default_target]</code> と <code>globs := #[.andSubmodules \\</code>ROOT_NAMESPACE]<code>を出し、</code>modules<code>を渡すと根 module が各 spec を</code>import<code>する。 壊れた spec を置いて</code>lake build\` が落ちることを test で固定した。</p><p><code>verifyLeanSpec</code> は Lake project を書かない。 書いて <code>lake</code> を呼ばないのが v0.2 までの姿で、 <code>lakefile.lean</code> は何にも影響していなかった。 影響しているのは <code>lean-toolchain</code> だけで、 <code>elan</code> がこの file を作業 directory から読んで実行する Lean の版を決める。 生成 spec は何も <code>import</code> しないので、 検査に build system は要らない。</p><h3 id="lean-の起動は-1-回-v0-3" tabindex="-1">Lean の起動は 1 回 (v0.3) <a class="header-anchor" href="#lean-の起動は-1-回-v0-3" aria-label="Permalink to &quot;Lean の起動は 1 回 (v0.3)&quot;">​</a></h3><p><code>lean</code> は file を 1 つしか受け取らない。 v0.2 は spec ごとに起動しており、 5 spec で約 660 ms かかった。 生成 spec は各自の namespace を開閉し何も import しないので、 1 file に結合しても検査内容は変わらない。 結合後は約 310 ms。</p><p>診断の位置は結合 file ではなく spec の名前で述べる。 namespace が重複する 2 spec は Lean が 2 つ目を名指しで拒否する。</p><p><code>moduleName</code> が同じ 2 spec は拒否する。 v0.2 は同じ path に 2 度書き、 先の spec を検査しないまま <code>verifiedFiles</code> に載せていた。</p><h3 id="対応する-lean-の版-v0-3-で実測" tabindex="-1">対応する Lean の版 (v0.3 で実測) <a class="header-anchor" href="#対応する-lean-の版-v0-3-で実測" aria-label="Permalink to &quot;対応する Lean の版 (v0.3 で実測)&quot;">​</a></h3><p>生成 source を v4.12.0 / v4.15.0 / v4.23.0 / v4.31.0 の 4 版で検証した。 4 版とも完全な表を受理し、 同じ壊れ方を拒否する。 診断の文言は版で変わる (<code>missing cases</code> → <code>Missing cases</code> が v4.23) ので、 test は Lean が echo し返す識別子で判定する。</p><p><code>verifyLeanSpec</code> は既定で版を固定しない。 machine の Lean が検査する。 <code>leanToolchain</code> を渡した時だけ <code>lean-toolchain</code> を書き、 <code>elan</code> がその版を走らせる。</p><h3 id="起動形と診断の出所-v0-3-で修正" tabindex="-1">起動形と診断の出所 (v0.3 で修正) <a class="header-anchor" href="#起動形と診断の出所-v0-3-で修正" aria-label="Permalink to &quot;起動形と診断の出所 (v0.3 で修正)&quot;">​</a></h3><p>Lean に <code>--check</code> flag は存在しない。 file を elaborate すること自体が検査で、 証明の失敗も網羅性の欠落も非零終了になる。 v0.2 は <code>lean --check FILE</code> を実行しており、 Lean は <code>unrecognized option</code> で常に非零終了していた。 つまり Lean が入っている環境では、 正しい spec も壊れた spec も等しく <code>verification-failed</code> を返していた。 toolchain を入れて実行する test が 1 件も無かったため、 誰も気付けなかった。</p><p>Lean は診断を <strong>stdout</strong> に書く。 <code>stderr</code> は空になる。 v0.2 の <code>VerifyResult.stderr</code> は常に空文字列で、 「検証に失敗した」 とだけ告げて理由を落としていた。 v0.3 は <code>diagnostics</code> に実際に喋った側の stream を載せる。</p><h3 id="決定的-ci-動作" tabindex="-1">決定的 CI 動作 <a class="header-anchor" href="#決定的-ci-動作" aria-label="Permalink to &quot;決定的 CI 動作&quot;">​</a></h3><p>Lean toolchain 未 install 環境 (CI default / offline / sandbox) は <code>lean-not-installed</code> で throw なし return、 CI が Lean install を待つ必要なし。 <code>KIWA_LEAN_SKIP_VERIFY=1</code> で 明示 skip 可能、 test suite 決定性維持。</p><h2 id="_5-lifecycle-orchestrator-の-2-軸融合仕様駆動開発-pipeline" tabindex="-1">5 lifecycle-orchestrator の 2 軸融合仕様駆動開発 pipeline <a class="header-anchor" href="#_5-lifecycle-orchestrator-の-2-軸融合仕様駆動開発-pipeline" aria-label="Permalink to &quot;5 lifecycle-orchestrator の 2 軸融合仕様駆動開発 pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrchestratorSpec (SSOT)</span></span>
<span class="line"><span>    ├─► generateLeanSpec → Lean 4 source</span></span>
<span class="line"><span>    │       └─► verifyLeanSpec → lean FILE → { status: &#39;ok&#39; }</span></span>
<span class="line"><span>    └─► TypeScript impl → vitest runtime testing</span></span></code></pre></div><p>同 SSOT (5 state / 8 event / 40 セル) を 両層で駆動、 Lean 側で網羅性 (catch-all 不在の match) と定理 (<code>STATE_absorbing</code> / <code>STATE_can_leave</code> / <code>STATE_no_escape</code> / <code>STATE_reachable</code>) を検査、 TS 側で 実行時挙動 verify。</p><h2 id="v2-15-milestone-signal" tabindex="-1">v2.15 milestone signal <a class="header-anchor" href="#v2-15-milestone-signal" aria-label="Permalink to &quot;v2.15 milestone signal&quot;">​</a></h2><ul><li>60 milestone streak (v1.23-v2.15)</li><li>4 PR rhythm 14 milestone 目 (v2.1-v2.15)</li><li>backward compat 絶対維持 23 milestone 連続 (v1.61-v2.15)</li><li>systematic pattern 57 度目 = Lean toolchain 統合</li><li>kiwa 全体 pipeline = testing + spec 生成 + spec 検証 の 3 段 完成</li><li>@kiwa-lab org 42 package 維持 (lean 既存 の minor 拡張)</li></ul>`,30)])])}const u=a(n,[["render",c]]);export{v as __pageData,u as default};
